import{_ as r,c as t,o as i,ah as l,j as o,a as n}from"./chunks/framework.CvbyeFFO.js";const v=JSON.parse('{"title":"AppWorld Agent框架相关","description":"","frontmatter":{"title":"AppWorld Agent框架相关","date":"2026-03-15T16:45:07.000Z","create":"2026-03-15T16:45:07.000Z","categories":["Appworld-Agent"],"tags":["HCL-GP","IBM CUGA","Generalized Planning","Hierarchical Planning"]},"headers":[],"relativePath":"posts/domain/appworld/02-appworld-agent.md","filePath":"posts/domain/appworld/02-appworld-agent.md","lastUpdated":null}'),d={name:"posts/domain/appworld/02-appworld-agent.md"},c={class:"custom-block note"},a={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},s={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"4.342ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 1919 1000","aria-hidden":"true"},g={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},p={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.666ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.908ex",height:"2.261ex",role:"img",focusable:"false",viewBox:"0 -705 843.3 999.2","aria-hidden":"true"};function u(m,e,h,T,A,b){return i(),t("div",null,[e[11]||(e[11]=l('<h2 id="_2605-ibm-learning-and-reusing-policy-decompositions-for-hierarchical-generalized-planning-with-llm-agents" tabindex="-1">(2605) (IBM) Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents <a class="header-anchor" href="#_2605-ibm-learning-and-reusing-policy-decompositions-for-hierarchical-generalized-planning-with-llm-agents" aria-label="Permalink to &quot;(2605) (IBM) Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents&quot;">​</a></h2><p>🌺 <strong>论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">HCL-GP 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2605.06957" target="_blank" rel="noreferrer">paper</a></li></ul><p><strong>核心方法 (HCL-GP, Hierarchical Component Learning for Generalized Policies)</strong></p><ul><li><code>核心想法</code>：不是每个Task都从零写代码，而是先学习一个能解决<code>同类任务</code>的参数化Policy。</li><li><code>Scenario-level Generalized Policy</code>： <ul><li>将AppWorld一个Scenario看成一个Domain。</li><li>同Scenario的多个任务共享Workflow，只把人物、金额、日期等差异变成参数。</li></ul></li><li><code>Hierarchical Component Learning</code>：成功Policy再拆成登录、分页、数据Join、交易等可复用Component。</li><li><code>复用闭环</code>：<code>生成Policy</code> -&gt; <code>提取Component</code> -&gt; <code>聚类泛化</code> -&gt; <code>环境验证</code> -&gt; <code>新Scenario检索复用</code>。</li></ul><p><strong>模型效果 (AppWorld)</strong></p><ul><li><code>Claude Sonnet 4.6 + HCL-GP</code>：Normal <code>TGC/SGC 98.2/98.2</code>，Challenge <code>98.3/97.8</code>。</li><li>不复用Component的Claude GP基线：Normal <code>96.4/96.4</code>，Challenge <code>83.2/82.0</code>；Challenge SGC提升<code>15.8</code>点。</li><li><code>GPT-OSS-120B + HCL-GP</code>：Normal <code>62.5/62.5</code>，Challenge <code>41.0/41.0</code>；不复用的GP基线接近0。</li></ul><p><strong>重要结论</strong></p><ul><li>AppWorld天然适合做<code>Generalized Planning</code>：同Scenario的任务通常是<code>流程相同、参数不同</code>。</li><li><code>强模型</code>：本身已经能生成较好Policy，Component主要减少Debug和Token；Challenge上准确率仍明显提升。</li><li><code>弱模型</code>：Component不是锦上添花，而是把Policy Synthesis从<code>几乎0分</code>拉到可用。</li><li>Component可以<code>跨App迁移</code>：训练阶段没有Gmail/Amazon，Challenge仍能受益。</li><li><code>注意比较口径</code>：该方法一次观察同Scenario多个Task，不能把98%直接和逐Task Agent排行榜做公平比较。</li></ul><p><strong>关键贡献</strong></p><ul><li>将Classical Generalized Planning与HTN式分解引入Model-free LLM Agent，无需手工Symbolic Domain Model。</li><li>提出“Policy生成 -&gt; Component提取 -&gt; Component泛化 -&gt; 后续组合复用”的执行闭环。</li><li>从最终成功率、Debug Iteration和Inference Cost三方面评估复用收益。</li></ul></div><h3 id="问题背景-每个任务都从零生成policy" tabindex="-1">问题背景(每个任务都从零生成Policy) <a class="header-anchor" href="#问题背景-每个任务都从零生成policy" aria-label="Permalink to &quot;问题背景(每个任务都从零生成Policy)&quot;">​</a></h3><p>❓<strong>问题背景</strong></p><div class="custom-block warning"><div class="custom-block-title">Task-level Agent没有积累程序性结构</div><p><strong>重复求解</strong></p><ul><li><code>Task-level Agent</code>把每个任务当成独立问题，登录、分页、Join、Filter、写入等操作需要反复探索。</li><li>同一Scenario的三个任务往往只是<code>参数不同</code>，但Agent仍要分别推理和Debug，历史代码没有真正沉淀下来。</li></ul><p><strong>Classical Planning启发</strong></p><ul><li>Generalized Planning学习一个能解决一类问题的Parameterized Policy。</li><li>HTN将复杂任务分解为可复用Sub-task。</li><li>传统方法依赖Symbolic State、Action Model和人工分解；AppWorld只提供自然语言任务、API和执行验证。</li></ul><p><strong>研究问题</strong></p><ul><li>能否仅凭成功执行代码与环境反馈，自动发现Hierarchical Component，并组合解决新Scenario？</li></ul></div><h3 id="核心架构-policy-generation-learning-generalization" tabindex="-1">核心架构(Policy Generation-Learning-Generalization) <a class="header-anchor" href="#核心架构-policy-generation-learning-generalization" aria-label="Permalink to &quot;核心架构(Policy Generation-Learning-Generalization)&quot;">​</a></h3><p>📕<strong>核心方法</strong></p>',8)),o("div",c,[e[8]||(e[8]=o("div",{class:"custom-block-title"},"1. Scenario-level Policy Generation",-1)),e[9]||(e[9]=o("p",null,[o("strong",null,"Task Abstraction & Parameterization Agent")],-1)),o("ul",null,[e[7]||(e[7]=o("li",null,"同时观察一个Scenario中的多个Task，抽取共享Workflow。",-1)),o("li",null,[e[4]||(e[4]=n("生成高层Steps、Policy Signature ")),o("mjx-container",a,[(i(),t("svg",s,e[0]||(e[0]=[l('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="mi"><path data-c="1D70E" d="M184 -11Q116 -11 74 34T31 147Q31 247 104 333T274 430Q275 431 414 431H552Q553 430 555 429T559 427T562 425T565 422T567 420T569 416T570 412T571 407T572 401Q572 357 507 357Q500 357 490 357T476 358H416L421 348Q439 310 439 263Q439 153 359 71T184 -11ZM361 278Q361 358 276 358Q152 358 115 184Q114 180 114 178Q106 141 106 117Q106 67 131 47T188 26Q242 26 287 73Q316 103 334 153T356 233T361 278Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(571,0)"><path data-c="28" d="M94 250Q94 319 104 381T127 488T164 576T202 643T244 695T277 729T302 750H315H319Q333 750 333 741Q333 738 316 720T275 667T226 581T184 443T167 250T184 58T225 -81T274 -167T316 -220T333 -241Q333 -250 318 -250H315H302L274 -226Q180 -141 137 -14T94 250Z" style="stroke-width:3;"></path></g><g data-mml-node="mi" transform="translate(960,0)"><path data-c="1D70B" d="M132 -11Q98 -11 98 22V33L111 61Q186 219 220 334L228 358H196Q158 358 142 355T103 336Q92 329 81 318T62 297T53 285Q51 284 38 284Q19 284 19 294Q19 300 38 329T93 391T164 429Q171 431 389 431Q549 431 553 430Q573 423 573 402Q573 371 541 360Q535 358 472 358H408L405 341Q393 269 393 222Q393 170 402 129T421 65T431 37Q431 20 417 5T381 -10Q370 -10 363 -7T347 17T331 77Q330 86 330 121Q330 170 339 226T357 318T367 358H269L268 354Q268 351 249 275T206 114T175 17Q164 -11 132 -11Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(1530,0)"><path data-c="29" d="M60 749L64 750Q69 750 74 750H86L114 726Q208 641 251 514T294 250Q294 182 284 119T261 12T224 -76T186 -143T145 -194T113 -227T90 -246Q87 -249 86 -250H74Q66 -250 63 -250T58 -247T55 -238Q56 -237 66 -225Q221 -64 221 250T66 725Q56 737 55 738Q55 746 60 749Z" style="stroke-width:3;"></path></g></g></g>',1)]))),e[1]||(e[1]=o("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[o("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[o("mi",null,"σ"),o("mo",{stretchy:"false"},"("),o("mi",null,"π"),o("mo",{stretchy:"false"},")")])],-1))]),e[5]||(e[5]=n(" 和每个任务的参数绑定 ")),o("mjx-container",g,[(i(),t("svg",p,e[2]||(e[2]=[l('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="msub"><g data-mml-node="mi"><path data-c="1D703" d="M35 200Q35 302 74 415T180 610T319 704Q320 704 327 704T339 705Q393 701 423 656Q462 596 462 495Q462 380 417 261T302 66T168 -10H161Q125 -10 99 10T60 63T41 130T35 200ZM383 566Q383 668 330 668Q294 668 260 623T204 521T170 421T157 371Q206 370 254 370L351 371Q352 372 359 404T375 484T383 566ZM113 132Q113 26 166 26Q181 26 198 36T239 74T287 161T335 307L340 324H145Q145 321 136 286T120 208T113 132Z" style="stroke-width:3;"></path></g><g data-mml-node="mi" transform="translate(502,-150) scale(0.707)"><path data-c="1D457" d="M297 596Q297 627 318 644T361 661Q378 661 389 651T403 623Q403 595 384 576T340 557Q322 557 310 567T297 596ZM288 376Q288 405 262 405Q240 405 220 393T185 362T161 325T144 293L137 279Q135 278 121 278H107Q101 284 101 286T105 299Q126 348 164 391T252 441Q253 441 260 441T272 442Q296 441 316 432Q341 418 354 401T367 348V332L318 133Q267 -67 264 -75Q246 -125 194 -164T75 -204Q25 -204 7 -183T-12 -137Q-12 -110 7 -91T53 -71Q70 -71 82 -81T95 -112Q95 -148 63 -167Q69 -168 77 -168Q111 -168 139 -140T182 -74L193 -32Q204 11 219 72T251 197T278 308T289 365Q289 372 288 376Z" style="stroke-width:3;"></path></g></g></g></g>',1)]))),e[3]||(e[3]=o("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[o("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[o("msub",null,[o("mi",null,"θ"),o("mi",null,"j")])])],-1))]),e[6]||(e[6]=n("。"))])]),e[10]||(e[10]=l("<p>本质上是把<code>3份具体程序</code>压缩成<code>1份带参数的通用程序</code>。</p><p><strong>Component Search Agent</strong></p><ul><li>根据Domain Abstraction从Validated Repository检索Top-20 Component。</li><li>同时从AppWorld API文档检索Top-20相关API。</li></ul><p><strong>Policy Generator Agent</strong></p><ul><li>综合Steps、Signature、Task Bindings、相关Component与API，生成一个Parameterized Python Policy。</li><li>在所有Scenario Task上实例化并执行；失败时利用Error Message、API Response和Partial Result最多Debug 3轮。</li></ul>",5))]),e[12]||(e[12]=l('<div class="custom-block note"><div class="custom-block-title">2. Learning Components</div><ul><li>Policy通过全部Task验证后，Decomposition Agent分析其Python代码。</li><li>提取实现完整Sub-task的函数，例如Authentication、Data Retrieval或Transaction Sequence。</li><li>同时重写原Policy，使其调用新Component。</li><li>重写Policy必须在原Scenario所有任务上再次通过，才把Component加入Learned Repository。</li></ul></div><div class="custom-block important"><div class="custom-block-title">3. Generalizing Components</div><ul><li>使用BAAI/bge-large-en-v1.5对Executable Code做Embedding。</li><li>以Cosine Similarity阈值<code>0.85</code>聚类相似Component。</li><li>Generalize &amp; Deduplicate Agent把窄函数合并为参数化抽象，例如： <ul><li><code>login_to_phone</code> + <code>login_to_venmo</code> -&gt; <code>login_to_app</code>。</li></ul></li><li>泛化Component及所有被重写Policy都必须重新执行验证。</li><li>验证通过后进入Validated Repository，供后续Scenario检索。</li></ul></div><h3 id="实验设置" tabindex="-1">实验设置 <a class="header-anchor" href="#实验设置" aria-label="Permalink to &quot;实验设置&quot;">​</a></h3><p>✍️<strong>实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型</strong></p><ul><li><code>Claude Sonnet 4.6</code>：强代码生成模型。</li><li><code>GPT-OSS-120B</code>：能力较弱的开源模型。</li></ul><p><strong>Component Seed构建</strong></p><ul><li>从AppWorld 30个Training Scenario开始，初始Repository为空。</li><li>使用Claude完成全部Training Scenario并提取Component。</li><li>第一轮得到101个Component，第二轮泛化后得到<code>159个Validated Component</code>。</li><li>同一个Claude构建的Seed Repository也用于GPT-OSS测试。</li></ul><p>因此GPT-OSS结果属于<code>开源执行模型 + Claude构建经验库</code>，不是完全不依赖闭源模型。</p><p><strong>评测</strong></p><ul><li>AppWorld Test-Normal与Test-Challenge。</li><li>Challenge包含训练未见的Gmail和Amazon。</li><li>报告TGC、SGC、累计Debug Iteration和Claude Token Cost。</li></ul><p><strong>基线</strong></p><ul><li><code>GP</code>：仍做Scenario-level Generalized Policy，但没有Component检索、学习与复用。</li><li>与AgentRL、CUGA、LOOP和Claude Task-level Agent结果并列比较。</li></ul></div><h3 id="关键结果" tabindex="-1">关键结果 <a class="header-anchor" href="#关键结果" aria-label="Permalink to &quot;关键结果&quot;">​</a></h3><p>🍑<strong>关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">模型效果</div><table tabindex="0"><thead><tr><th>方法</th><th style="text-align:right;">Normal TGC / SGC</th><th style="text-align:right;">Challenge TGC / SGC</th></tr></thead><tbody><tr><td>GPT-OSS GP</td><td style="text-align:right;">0.0 / 0.0</td><td style="text-align:right;">0.7 / 0.7</td></tr><tr><td>GPT-OSS HCL-GP</td><td style="text-align:right;"><strong>62.5 / 62.5</strong></td><td style="text-align:right;"><strong>41.0 / 41.0</strong></td></tr><tr><td>Claude GP</td><td style="text-align:right;">96.4 / 96.4</td><td style="text-align:right;">83.2 / 82.0</td></tr><tr><td>Claude HCL-GP</td><td style="text-align:right;"><strong>98.2 / 98.2</strong></td><td style="text-align:right;"><strong>98.3 / 97.8</strong></td></tr></tbody></table><p><strong>Reuse最有价值的场景</strong></p><ul><li><code>Claude + Normal</code>：本来已经接近饱和，Reuse只提升<code>1.8 SGC</code>。</li><li><code>Claude + Challenge</code>：涉及未见App和复杂流程，Reuse提升<code>15.8 SGC</code>。</li><li><code>GPT-OSS</code>：没有Component时几乎无法合成Policy；复用后Normal达到<code>62.5 SGC</code>。</li></ul><p><strong>效率与成本</strong></p><ul><li>HCL-GP在相同成功率下需要更少Debug Iteration。</li><li>Dynamic Reuse把Cost-Accuracy Curve整体向左上移动，尤其在Challenge明显。</li></ul><p><strong>Component使用分析</strong></p><ul><li>Learned Component利用率Normal约<code>75%</code>、Challenge约<code>60%</code>，高于Seed Component的<code>26%-29%</code>。</li><li>Challenge平均每个Scenario使用<code>6.4</code>个Learned Component，Normal为<code>3.8</code>，反映难任务需要更强组合。</li><li>少数泛化Seed Component复用率很高，但大量在线Learned Component仍偏Task-specific。</li></ul><p><strong>比较时的重要口径</strong></p><ul><li>HCL-GP同时接收一个Scenario中的多个相关任务来抽象Policy，而Leaderboard方法通常逐Task独立求解。</li><li>因此<code>98%</code>不能简单解释为同一Agent协议下直接超过所有Task-level方法；它同时利用了Scenario结构和额外的跨任务输入。</li><li>GPT-OSS实验也复用了Claude构建的159个Component，不能视为完全不依赖闭源模型的纯开源结果。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><p><strong>⛳未来方向</strong></p><div class="custom-block info"><div class="custom-block-title">未来展望</div><ul><li>目前Component是Flat Library，可进一步学习Dependency Graph与多层Hierarchy。</li><li>Generalization和Deduplication在一次LLM调用中完成，Repository扩大后容易超过Context Limit，应拆成多阶段增量流程。</li><li>AppWorld提供干净的Scenario边界；真实环境需要先自动发现哪些任务共享程序结构。</li><li>方法依赖固定Action Space、Deterministic Execution和Validator，开放环境中的Action Discovery与不完备验证仍困难。</li><li>需要在Scenario信息不可同时获得的Streaming Setting中评测，确认动态复用对真实逐任务到达流程的价值。</li></ul></div><h2 id="_2510-ibm-cuga-from-benchmarks-to-business-impact-deploying-ibm-generalist-agent-in-enterprise-production" tabindex="-1">(2510) IBM CUGA) From Benchmarks to Business Impact: Deploying IBM Generalist Agent in Enterprise Production <a class="header-anchor" href="#_2510-ibm-cuga-from-benchmarks-to-business-impact-deploying-ibm-generalist-agent-in-enterprise-production" aria-label="Permalink to &quot;(2510) IBM CUGA) From Benchmarks to Business Impact: Deploying IBM Generalist Agent in Enterprise Production&quot;">​</a></h2><p>🌺 <strong>论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">CUGA: Enterprise Generalist Agent 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2510.23856v2" target="_blank" rel="noreferrer">paper</a></li></ul><p><strong>核心方法</strong></p><ul><li><code>CUGA架构</code> (Computer Using Generalist Agent) <ul><li><code>分层规划-执行器架构</code><ul><li>Chat层(预处理) -&gt; <code>外循环(任务规划/账本)</code> -&gt; <code>内循环(API/Web/Code子Agent执行)</code></li></ul></li><li><code>可靠性机制</code><ul><li>基于<code>Schema的Prompting</code>、变量追踪、<code>反思性重试</code>(Reflective Retries)。</li></ul></li></ul></li><li><code>企业级适配</code><ul><li><code>API/Tool Hub</code>：<code>集中化管理API</code>，简化OpenAPI Spec。</li><li><code>治理与安全</code>：<code>来源日志</code>(Provenance Logging)、<code>沙箱代码执行</code>、Human-in-the-Loop。</li></ul></li></ul><p><strong>模型效果</strong></p><ul><li><strong>学术榜单</strong>：<code>WebArena</code> (61.7% SOTA) 和 <code>AppWorld</code> (48.2% SOTA)。</li><li><strong>企业试点(BPO-TA)</strong>： <ul><li>准确率达<code>87%</code>，复现性高。</li><li>相比手写专用Agent，开发时间减少<code>90%</code>，成本降低<code>50%</code>。</li><li>单个任务耗时从人工<code>20分钟</code>降至<code>2-5分钟</code>。</li></ul></li></ul><p><strong>重要结论</strong></p><ul><li>通用Agent架构(Generalist)比专用Agent(Specialized)更具<code>成本效益</code>和<code>扩展性</code>。</li><li>企业部署的关键不在于模型能力，而在于<code>治理</code>、<code>可审计性</code>和<code>无幻觉的拒绝能力</code>。</li></ul><p><strong>关键贡献</strong></p><ul><li>提出了<code>BPO-TA Benchmark</code> (业务流程外包-人才招聘基准)，包含26个真实分析任务。</li><li>验证了通用Agent在<code>企业生产环境</code>的可行性与经济效益。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>❓<strong>问题背景</strong></p><div class="custom-block warning"><div class="custom-block-title">原型demo到生产应用存在挑战</div><p><strong>企业需求与现状的错位</strong></p><ul><li>企业面临巨大的自动化压力，但从<code>Research</code>到<code>Deployment</code>极其困难。</li><li><code>原型陷阱</code>：ReAct等简单架构在Demo时表现良好，但在处理复杂流程、多工具时<code>极其脆弱</code>。</li><li><code>缺乏标准</code>：学术界关注Benchmarks，企业关注SLA、审计合规和ROI，两者缺乏桥梁。</li></ul><p><strong>专用Agent的局限</strong></p><ul><li>传统做法是为每个任务手写<code>Specialized Agent</code>。</li><li>缺点：<code>开发周期长</code> (3-9个月)、<code>维护成本高</code>、难以跨领域复用。</li></ul></div><div class="custom-block warning"><div class="custom-block-title">通用Agent 优势</div><p><strong>核心假设</strong></p><ul><li>通用Agent (如CUGA) 经过复杂Benchmark训练，具备<code>强规划</code>和<code>工具使用</code>能力。</li><li>企业只需进行<code>配置</code>和<code>领域适配</code>，无需从头开发。</li><li>目标：将开发模式从“从零构建”转变为“配置与基准测试”。</li></ul></div><p>📕<strong>核心方法</strong></p><h3 id="架构设计-layered-planner-executor" tabindex="-1">架构设计 (Layered Planner-Executor) <a class="header-anchor" href="#架构设计-layered-planner-executor" aria-label="Permalink to &quot;架构设计 (Layered Planner-Executor)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">架构详解</div><p><strong>三层控制结构</strong></p><ol><li><strong>Chat Layer</strong>：输入预处理、上下文管理。</li><li><strong>Outer Loop (规划层)</strong>： <ul><li><code>Task Analyzer</code>：分析任务意图。</li><li><code>Plan Controller</code>：维护持久化账本 (Ledger)，记录步骤、变量和状态，确保可追溯。</li></ul></li><li><strong>Inner Loop (执行层)</strong>： <ul><li><code>API Sub-Agent</code>：通过<code>API Planner</code>和<code>Shortlister</code>选择工具，支持代码沙箱执行。</li><li><code>Browser Sub-Agent</code>：支持基于Playwright的网页操作 (本次试点因合规暂时禁用)。</li></ul></li></ol><p><strong>可靠性增强</strong></p><ul><li><code>Reflective Retries</code>：当工具调用失败或参数错误时，触发反思修正，而非直接报错。</li><li><code>Interrupt Nodes</code>：显式的逻辑检查节点，防止执行偏航。</li><li><code>API/Tool Hub</code>：对原始OpenAPI Spec进行<code>最小化</code>和<code>标准化</code>处理，降低LLM理解难度。</li></ul></div><img src="https://arxiv.org/html/2510.23856v1/images/arch.png" style="display:block;margin:auto;" width="70%"><h3 id="企业级治理适配" tabindex="-1">企业级治理适配 <a class="header-anchor" href="#企业级治理适配" aria-label="Permalink to &quot;企业级治理适配&quot;">​</a></h3><div class="custom-block note"><div class="custom-block-title">安全与合规</div><p><strong>审计与透明度</strong></p><ul><li><code>Provenance Logging</code>：所有回答必须附带“来源面板”，列出调用的API路径、参数和计算日志。</li><li><code>Read-Only 模式</code>：在BPO试点中仅开放读权限，确保数据安全。</li><li><code>PII 过滤</code>：自动脱敏个人隐私信息。</li></ul><p><strong>Human-in-the-Loop (HITL)</strong></p><ul><li><code>可配置的自主权</code>：业务方可定义哪些步骤Agent可自动执行，哪些必须人工确认。</li></ul></div><h3 id="实验设置-gpt4-1" tabindex="-1">实验设置(GPT4.1) <a class="header-anchor" href="#实验设置-gpt4-1" aria-label="Permalink to &quot;实验设置(GPT4.1)&quot;">​</a></h3><p>✍️<strong>实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>基准测试</strong></p><ul><li><strong>学术基准</strong>： <ul><li><code>WebArena</code> (网页浏览/操作)</li><li><code>AppWorld</code> (多API编排/代码生成)</li></ul></li><li><strong>企业基准 (新提出)</strong>： <ul><li><code>BPO-TA</code> (Business Process Outsourcing - Talent Acquisition)</li><li>包含<code>13个分析API</code> (如SLA分析、漏斗转化率等) 和 <code>26个典型任务</code>。</li><li>任务类型涵盖：简单查找、跨API Join、循环推理、溯源解释、不支持功能的优雅拒绝。</li></ul></li></ul><p><strong>评估指标</strong></p><ul><li><code>Task Accuracy</code> (任务准确率)</li><li><code>Valid First-Try Rate</code> (一次通过率)</li><li><code>Reproducibility</code> (结果复现性)</li><li><code>Time-to-Answer</code> (回答耗时)</li><li><code>Provenance Coverage</code> (来源日志覆盖率)</li></ul></div><h3 id="关键结果-1" tabindex="-1">关键结果 <a class="header-anchor" href="#关键结果-1" aria-label="Permalink to &quot;关键结果&quot;">​</a></h3><p>🍑<strong>关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">实验结果</div><p><strong>学术SOTA表现</strong></p><ul><li><strong>WebArena</strong>：总准确率 <code>61.7%</code> (Reddit任务达75.5%)，超越现有开源Agent。</li><li><strong>AppWorld</strong>：Test-Challenge场景完成率 <code>48.2%</code>，Level 1任务达87.5%。</li></ul><p><strong>企业试点收益 (BPO-TA)</strong></p><ul><li><strong>准确率</strong>：达到 <code>87%</code>，且在不支持的查询上实现了无幻觉拒绝。</li><li><strong>效率提升</strong>： <ul><li>人工分析需 <code>20分钟</code> -&gt; CUGA仅需 <code>2-5分钟</code> (效率提升~90%)。</li><li>开发成本相比专用Agent降低 <code>50%</code>。</li></ul></li><li><strong>可审计性</strong>：<code>95%</code> 的回答包含了完整的来源日志 (Provenance Logs)。</li></ul><p><strong>重要结论</strong></p><ul><li><strong>反思机制至关重要</strong>：去掉Reflective Retries后，性能下降11个点。</li><li><strong>变量追踪影响复现</strong>：去掉显式变量追踪，复现性评分大幅下降。</li><li><strong>通用架构可行</strong>：证明了“通用架构 + 领域配置”可以替代昂贵的定制开发。</li></ul></div><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><p>⛳ <strong>未来方向</strong></p><div class="custom-block info"><div class="custom-block-title">后续计划</div><p><strong>技术演进</strong></p><ul><li><strong>自适应短路</strong>：利用记忆或缓存跳过重复规划步骤，降低延迟和成本。</li><li><strong>轨迹复用</strong>：将成功的执行轨迹转化为新的“工具”，供后续调用。</li><li><strong>小模型蒸馏</strong>：针对高频简单任务，使用更小的模型以降低成本。</li></ul><p><strong>组织与治理</strong></p><ul><li><strong>更细粒度的HITL</strong>：不仅是开关，而是基于策略的动态人工介入。</li><li><strong>写操作上线</strong>：从Read-Only逐步过渡到受控的Create/Update操作。</li><li><strong>扩展领域</strong>：将架构推广到财务、采购、法务等其他企业部门。</li></ul></div><h2 id="_2503-ibm-cuga-towards-enterprise-ready-computer-using-generalist-agent" tabindex="-1">(2503) (IBM CUGA)Towards Enterprise-Ready Computer Using Generalist Agent <a class="header-anchor" href="#_2503-ibm-cuga-towards-enterprise-ready-computer-using-generalist-agent" aria-label="Permalink to &quot;(2503) (IBM CUGA)Towards Enterprise-Ready Computer Using Generalist Agent&quot;">​</a></h2><p>🌺 <strong>论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2503.01861" target="_blank" rel="noreferrer">paper</a></li></ul><p><strong>核心方法</strong></p><ul><li><code>CUGA (Computer Using Generalist Agent)</code><ul><li>针对<code>企业级需求</code>设计的通用计算机操作智能体。</li><li><code>分层多agent架构</code>：<code>Plan Controller</code> (高层规划) + <code>Sub-task Agents</code> (Web/API 子任务执行)。</li></ul></li><li><code>迭代式演进方法</code><ul><li>提出<code>Evaluate-Analyze-Enhance</code> Loop。</li><li>使用<code>Smart Sampling</code>策略：从<code>小样本</code>开始快速迭代，<code>逐步扩大测试</code>范围。</li></ul></li><li><code>工具链支持</code><ul><li>开发了<code>性能仪表盘</code>、<code>轨迹可视化工具</code>和<code>并行执行框架</code>以加速开发。</li></ul></li></ul><p><strong>模型效果</strong></p><ul><li><strong>WebArena</strong>: 达到 <code>61.7%</code> 的任务成功率 (SOTA)。</li><li><strong>AppWorld</strong>: 达到 <code>48.2%</code> 的场景完成率 (SOTA)，在多步骤API交互上表现出色。</li></ul><p><strong>重要结论</strong></p><ul><li>简单的<code>Plan-Act-Observe</code>循环无法处理长程任务，需拆分为<code>规划器</code>和<code>执行器</code>。</li><li><code>Web与API</code>需采用不同的感知和交互策略（如Web用<code>截图+无障碍树</code>，API用<code>MCP+注册表</code>）。</li><li><code>Smart Sampling</code>（智能采样）显著降低了评估成本并加快了开发速度。</li></ul><p><strong>关键贡献</strong></p><ul><li>公开了实现<code>WebArena</code>和<code>AppWorld</code> <code>双榜SOTA</code>的<code>架构演进路线</code>。</li><li>分享了企业级Agent开发的<code>方法论</code>和<code>工具链</code>经验。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>❓<strong>问题背景</strong></p><div class="custom-block warning"><div class="custom-block-title">问题背景</div><p><strong>企业级Agent的挑战</strong></p><ul><li>现有Agent研究主要在<code>刷榜</code>，但<code>企业级应用</code>更关注<code>隐私</code>、<code>安全</code>、<code>可信度</code>和<code>成本</code>。</li><li>简单Agent架构在处理<code>长程任务</code>、<code>多应用切换</code>和<code>复杂逻辑</code>时<code>表现不佳</code>。</li></ul><p><strong>现有基准测试的局限</strong></p><ul><li>学术界Benchmark（如<code>WebArena</code>）通常基于<code>静态环境</code>或<code>单一模态</code>。</li><li>缺乏对<code>API交互</code>、<code>变量管理</code>及<code>动态策略调整</code>的综合评估。</li><li>即使OpenAI Operator或<code>Anthropic Computer Use</code>，在落地企业<code>复杂工作流</code>时<code>仍有挑战</code>。</li></ul></div><h3 id="分层多agent-smart-sampling" tabindex="-1">分层多Agent+Smart Sampling <a class="header-anchor" href="#分层多agent-smart-sampling" aria-label="Permalink to &quot;分层多Agent+Smart Sampling&quot;">​</a></h3><p>📕<strong>核心方法</strong></p><div class="custom-block note"><div class="custom-block-title">架构演进：分层多智能体</div><p><strong>整体架构</strong></p><ul><li><strong>Plan Controller Agent (高层规划)</strong><ul><li>负责<code>任务分解</code>、<code>子任务排序</code>、<code>循环/条件逻辑</code>处理。</li><li>核心能力：<code>跨任务变量传递</code>（Variable Passing），维护全局上下文。</li></ul></li><li><strong>Sub-task Plan-Execute Agents (子任务执行)</strong><ul><li>专注于局部执行，分为<code>Browser Agent</code>和<code>API Agent</code>。</li></ul></li></ul><p><strong>Browser Sub-agent (Web端)</strong></p><ul><li><strong>感知</strong>：结合<code>截图</code> (Screenshots) 和 <code>无障碍树</code> (Accessibility Tree)。</li><li><strong>操作</strong>：使用 <code>Playwright</code> 进行浏览器控制。</li><li><strong>改进</strong>： <ul><li>引入<code>专用信息提取Agent</code>，将交互与提取解耦。</li><li>增加<code>反馈循环</code>，处理弹窗遮挡和动态UI变化。</li></ul></li></ul><p><strong>API Sub-agent (服务端)</strong></p><ul><li><strong>感知</strong>：利用 <code>API Registry</code> 管理OpenAPI Schema，通过 <code>MCP</code> (Model Context Protocol) 动态加载工具。</li><li><strong>操作</strong>：支持复杂API调用、结果解析和变量管理。</li><li><strong>改进</strong>： <ul><li><code>OpenAPI精简</code>：压缩Schema以减少Token消耗。</li><li><code>反射机制</code>：处理API报错和非预期输出。</li></ul></li></ul></div><img src="https://arxiv.org/html/2503.01861v3/extracted/6609269/images/CUGA-Architecture.png" style="display:block;margin:auto;" width="70%"><p>AppWorld：</p><img src="https://arxiv.org/html/2503.01861v3/extracted/6609269/images/api.png" style="display:block;margin:auto;" width="70%"><div class="custom-block note"><div class="custom-block-title">开发方法论：Smart Sampling</div><p><strong>迭代策略</strong></p><ul><li>摒弃每次都跑全量测试的低效做法。</li><li><strong>采样阶段</strong>： <ul><li><code>Nano</code> (44样本) -&gt; <code>Micro</code> (90样本) -&gt; <code>Mini</code> (190样本) -&gt; <code>Full</code> (812样本)。</li><li>在小样本上快速验证假设，修复Fail case，逐步扩大规模以测试泛化性。</li></ul></li></ul><p><strong>配套工具</strong></p><ul><li><strong>轨迹可视化</strong>：直观展示Agent的感知（截图/Dom树）、思考和动作，便于归因分析。</li><li><strong>并行执行</strong>：将评估时间从“天”级缩短至“分钟”级。</li></ul></div><h3 id="实验设置-1" tabindex="-1">实验设置 <a class="header-anchor" href="#实验设置-1" aria-label="Permalink to &quot;实验设置&quot;">​</a></h3><p>✍️<strong>实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>基础模型</strong></p><ul><li>使用 <code>Frontier LLMs</code> (如 GPT-4.1 等，通过 LangChain 统一接口调用)。</li></ul><p><strong>评测数据</strong></p><ul><li><strong>WebArena</strong>: 包含电子商务、论坛、CMS等Web任务。</li><li><strong>AppWorld</strong>: 包含代码执行、多API调用、数据库查询等复杂任务。</li></ul><p><strong>评测指标</strong></p><ul><li>WebArena：<code>Success Rate</code> (成功率)，</li><li>AppWorld：<code>Scenario Completion Rate</code> (场景完成率，要求完成<code>同一场景下的所有任务</code>)</li></ul><p><strong>算法/策略</strong></p><ul><li><code>ReAct</code> 范式基础上的分层规划。</li><li><code>LangGraph</code> 用于状态管理和多Agent编排。</li><li><code>Reflection</code> (反思) 机制用于错误恢复。</li></ul></div><img src="https://arxiv.org/html/2503.01861v3/extracted/6609269/images/trajectory_api.png" style="display:block;margin:auto;" width="70%"><h3 id="关键结果-gpt4-1" tabindex="-1">关键结果(GPT4.1) <a class="header-anchor" href="#关键结果-gpt4-1" aria-label="Permalink to &quot;关键结果(GPT4.1)&quot;">​</a></h3><p>🍑<strong>关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>WebArena 表现</strong></p><ul><li>CUGA 实现了 <code>61.7%</code> 的成功率，刷新了 SOTA。</li><li>相比初始的简单Agent架构（15%），通过架构拆分和针对性优化提升了4倍以上。</li></ul><p><strong>AppWorld 表现</strong></p><ul><li><strong>总榜 SOTA</strong>：TGC-Normal-Challenge <code>73.2%</code>、<code>57.6%</code>，其中SGC-Challenge是<code>48.2%</code></li><li><strong>分级表现</strong>： <ul><li><code>Level 1</code> (简单API): 任务完成率 &gt;91%。</li><li><code>Level 3</code> (复杂逻辑): 场景完成率降至 ~38%，表明<code>复杂推理仍是难点</code>。</li></ul></li><li><strong>行为分析</strong>：随任务难度增加，<code>平均交互次数显著上升</code>，表明Agent<code>具备动态调整策略的能力</code>。</li></ul><p><strong>重要结论</strong></p><ul><li><code>分离关注点是关键</code>：<code>高层</code>关注<code>流程</code>，<code>底层</code>关注<code>操作</code>，能显著<code>提升长程任务稳定性</code>。</li><li><code>环境感知增强</code>（如Web端的截图+Dom树结合，API端的<code>Schema精简</code>）对<code>减少幻觉</code>至关重要。</li></ul></div><h3 id="未来方向-2" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-2" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><p>⛳ <strong>未来方向</strong></p><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>企业级安全与合规</strong></p><ul><li>目前主要关注任务完成率，未来将重点评估<code>安全性</code>（Safety）和<code>策略依从性</code>（Policy Adherence）。</li><li>探索在API调用中加入<code>安全验证层</code>，防止Agent进行危险操作。</li></ul><p><strong>降低成本</strong></p><ul><li>目前依赖前沿大模型（Frontier Models）。</li><li>计划蒸馏或迁移至<code>更小的开源模型</code>，以降低企业部署成本。</li></ul><p><strong>自动化进化</strong></p><ul><li>目前的错误分析仍需人工介入。</li><li>计划开发<code>Agentic Analysis</code>，让Agent自动分析失败轨迹并提出改进建议，实现系统的自我进化。</li></ul></div>',56))])}const C=r(d,[["render",u]]);export{v as __pageData,C as default};
